<?php
require_once __DIR__.'/lesson_groups.php';
function payrollLinkDate($value){if(!preg_match('~(\d{4})/(\d{1,2})/(\d{1,2})~',str_replace('-','/',(string)$value),$m))return '';return sprintf('%04d-%02d-%02d',(int)$m[1],(int)$m[2],(int)$m[3]);}
function payrollOtherLesson($row){$source=trim((string)($row['_sourceKey']??''));$subjects=array_values(array_filter(array_map('trim',preg_split('/[,、，]/u',(string)($row['科目']??'')))));$date=payrollLinkDate($row['日付']??'');$key=implode('|',[$date,trim((string)($row['時間番号']??'')),trim((string)($row['クラス']??'')),trim((string)($row['担当講師']??'')),trim((string)($row['種別']??'')),implode('+',$subjects)]);return ['sourceKey'=>$source,'date'=>$date,'slot'=>trim((string)($row['時間番号']??'')),'start'=>groupRowTime($row,'開始'),'end'=>groupRowTime($row,'終了'),'className'=>trim((string)($row['クラス']??'')),'teacher'=>trim((string)($row['担当講師']??'')),'room'=>trim((string)($row['教室']??'')),'key'=>$key,'url'=>$source!==''?'payroll.php?lessonSource='.rawurlencode($source):null];}
function payrollSourceLocation($source){if(!is_string($source)||$source===''||strlen($source)>4000)return null;foreach(policyRows() as $row){if(($row['_sourceKey']??'')!==$source||trim((string)($row['日区分']??''))!=='')continue;$lesson=payrollOtherLesson($row);if($lesson['date']==='')return null;return 'teacher2026summer_vertical.html?'.http_build_query(['teacher'=>$lesson['teacher'],'date'=>$lesson['date'],'openKey'=>$lesson['key'],'openSource'=>$source],'','&',PHP_QUERY_RFC3986);}return null;}
